import{_ as t,c as e,o as r,ag as i}from"./chunks/framework.CMajxlqO.js";const p=JSON.parse('{"title":"Profinet-konfiguration i TIA Portal","description":"","frontmatter":{},"headers":[],"relativePath":"06-kommunikation/profinet-konfiguration.md","filePath":"06-kommunikation/profinet-konfiguration.md","lastUpdated":1768470380000}'),n={name:"06-kommunikation/profinet-konfiguration.md"};function l(o,a,s,d,g,h){return r(),e("div",null,[...a[0]||(a[0]=[i(`<h1 id="profinet-konfiguration-i-tia-portal" tabindex="-1">Profinet-konfiguration i TIA Portal <a class="header-anchor" href="#profinet-konfiguration-i-tia-portal" aria-label="Permalink to &quot;Profinet-konfiguration i TIA Portal&quot;">​</a></h1><p>Profinet-konfiguration i TIA Portal handlar om att skapa ett <strong>IO-system</strong> där din PLC (IO Controller) kommunicerar med enheter (IO Devices) som HMI, frekvensomriktare och fjärr-I/O-moduler.</p><h2 id="steg-for-steg-konfigurera-profinet" tabindex="-1">Steg-för-steg: Konfigurera Profinet <a class="header-anchor" href="#steg-for-steg-konfigurera-profinet" aria-label="Permalink to &quot;Steg-för-steg: Konfigurera Profinet&quot;">​</a></h2><h3 id="_1-oppna-network-view" tabindex="-1">1. Öppna Network view <a class="header-anchor" href="#_1-oppna-network-view" aria-label="Permalink to &quot;1. Öppna Network view&quot;">​</a></h3><ol><li>Dubbelklicka på <strong>Device &amp; Networks</strong> i projektträdet</li><li>Välj <strong>Network view</strong> (eller tryck Ctrl+Shift+N)</li><li>Här ser du alla enheter och deras nätverksanslutningar</li></ol><h3 id="_2-konfigurera-plc-ns-ip-adress" tabindex="-1">2. Konfigurera PLC:ns IP-adress <a class="header-anchor" href="#_2-konfigurera-plc-ns-ip-adress" aria-label="Permalink to &quot;2. Konfigurera PLC:ns IP-adress&quot;">​</a></h3><ol><li>Dubbelklicka på PLC:n → <strong>Device view</strong></li><li>Klicka på <strong>Profinet-porten</strong> (grön kontakt)</li><li>I <strong>Properties</strong> → <strong>Ethernet addresses</strong>: <ul><li><strong>IP address</strong>: <code>192.168.0.1</code></li><li><strong>Subnet mask</strong>: <code>255.255.255.0</code></li><li><strong>Use router</strong>: Markera om du har gateway</li></ul></li></ol><div class="tip custom-block"><p class="custom-block-title">Standard IP-schema</p><table tabindex="0"><thead><tr><th>Enhetstyp</th><th>IP-intervall</th></tr></thead><tbody><tr><td>PLC</td><td>192.168.0.1 - 192.168.0.9</td></tr><tr><td>HMI</td><td>192.168.0.10 - 192.168.0.19</td></tr><tr><td>Drives</td><td>192.168.0.20 - 192.168.0.29</td></tr><tr><td>Fjärr-I/O</td><td>192.168.0.30 - 192.168.0.39</td></tr></tbody></table></div><h3 id="_3-lagg-till-enheter" tabindex="-1">3. Lägg till enheter <a class="header-anchor" href="#_3-lagg-till-enheter" aria-label="Permalink to &quot;3. Lägg till enheter&quot;">​</a></h3><h4 id="fran-hardware-catalog" tabindex="-1">Från Hardware catalog: <a class="header-anchor" href="#fran-hardware-catalog" aria-label="Permalink to &quot;Från Hardware catalog:&quot;">​</a></h4><ol><li>Öppna <strong>Hardware catalog</strong> (höger sida)</li><li>Navigera till önskad enhet, ex: <ul><li><strong>HMI</strong> → Basic Panels → KTP700 Basic</li><li><strong>Distributed I/O</strong> → ET 200SP</li><li><strong>Drives</strong> → SINAMICS G120</li></ul></li><li><strong>Dra och släpp</strong> enheten till Network view</li><li>Konfigurera IP-adress för varje enhet</li></ol><h4 id="importera-via-gsdml" tabindex="-1">Importera via GSDML: <a class="header-anchor" href="#importera-via-gsdml" aria-label="Permalink to &quot;Importera via GSDML:&quot;">​</a></h4><p>För tredjepartsenheter eller specifika moduler:</p><ol><li><strong>Options</strong> → <strong>Manage general station description files (GSD)</strong></li><li>Klicka <strong>Installed GSDs</strong> → <strong>Install</strong></li><li>Bläddra till <code>.xml</code> eller <code>.gsdml</code>-fil</li><li>Enheten visas nu i Hardware catalog</li></ol><h3 id="_4-skapa-profinet-anslutningar" tabindex="-1">4. Skapa Profinet-anslutningar <a class="header-anchor" href="#_4-skapa-profinet-anslutningar" aria-label="Permalink to &quot;4. Skapa Profinet-anslutningar&quot;">​</a></h3><ol><li>I <strong>Network view</strong>, håll musen över PLC:ns Profinet-port</li><li>En <strong>grön pil</strong> visas</li><li><strong>Dra</strong> från PLC till enhetens Profinet-port</li><li>En <strong>grön linje</strong> skapas = IO-relation etablerad</li></ol><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>    [PLC S7-1200]</span></span>
<span class="line"><span>         |</span></span>
<span class="line"><span>    [Profinet Switch]</span></span>
<span class="line"><span>    /    |    \\</span></span>
<span class="line"><span>[HMI] [G120] [ET200SP]</span></span></code></pre></div><h3 id="_5-tilldela-io-device-namn" tabindex="-1">5. Tilldela IO Device-namn <a class="header-anchor" href="#_5-tilldela-io-device-namn" aria-label="Permalink to &quot;5. Tilldela IO Device-namn&quot;">​</a></h3><p>Varje IO Device måste ha ett <strong>unikt enhetsnamn</strong> (Device name) som matchar konfigurationen.</p><ol><li>Markera enheten i Network view</li><li><strong>Properties</strong> → <strong>General</strong> → <strong>Name</strong></li><li>Ange namn, ex: <code>hmi-panel-1</code>, <code>drive-pump-01</code></li></ol><div class="warning custom-block"><p class="custom-block-title">Viktigt</p><p>Device name är <strong>skiftlägeskänsligt</strong> och måste vara exakt samma som det som tilldelas fysiskt till enheten!</p></div><h2 id="tilldela-device-name-till-fysisk-enhet" tabindex="-1">Tilldela Device name till fysisk enhet <a class="header-anchor" href="#tilldela-device-name-till-fysisk-enhet" aria-label="Permalink to &quot;Tilldela Device name till fysisk enhet&quot;">​</a></h2><h3 id="metod-1-via-tia-portal-online" tabindex="-1">Metod 1: Via TIA Portal (Online) <a class="header-anchor" href="#metod-1-via-tia-portal-online" aria-label="Permalink to &quot;Metod 1: Via TIA Portal (Online)&quot;">​</a></h3><ol><li><strong>Online</strong> → <strong>Accessible devices</strong></li><li>Klicka <strong>Update</strong> för att skanna nätverket</li><li>Markera enheten (identifieras via MAC-adress)</li><li>Klicka <strong>Assign name</strong> → Ange Device name</li><li>Klicka <strong>Assign IP address</strong> → Ange IP-konfiguration</li></ol><h3 id="metod-2-via-siemens-proneta" tabindex="-1">Metod 2: Via Siemens PRONETA <a class="header-anchor" href="#metod-2-via-siemens-proneta" aria-label="Permalink to &quot;Metod 2: Via Siemens PRONETA&quot;">​</a></h3><ol><li>Ladda ner <strong>PRONETA Basic</strong> (gratis) från Siemens</li><li>Kör <strong>Network scan</strong></li><li>Högerklicka på enhet → <strong>Assign device name</strong></li><li>Använd samma namn som i TIA Portal</li></ol><h2 id="io-adressering" tabindex="-1">IO-adressering <a class="header-anchor" href="#io-adressering" aria-label="Permalink to &quot;IO-adressering&quot;">​</a></h2><p>När du lägger till en IO Device tilldelas automatiskt <strong>I/O-adresser</strong>.</p><h3 id="kontrollera-adresser" tabindex="-1">Kontrollera adresser: <a class="header-anchor" href="#kontrollera-adresser" aria-label="Permalink to &quot;Kontrollera adresser:&quot;">​</a></h3><ol><li>Dubbelklicka på enheten → <strong>Device view</strong></li><li>Varje modul visar <strong>I address</strong> och <strong>Q address</strong></li><li>Dessa används i PLC-programmet</li></ol><p><strong>Exempel för ET 200SP:</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>DI 8x24V:     I0.0 - I0.7</span></span>
<span class="line"><span>DO 8x24V:     Q0.0 - Q0.7</span></span>
<span class="line"><span>AI 4x16bit:   IW64 - IW70</span></span></code></pre></div><h3 id="andra-startadress" tabindex="-1">Ändra startadress: <a class="header-anchor" href="#andra-startadress" aria-label="Permalink to &quot;Ändra startadress:&quot;">​</a></h3><ol><li>Markera modulen i Device view</li><li><strong>Properties</strong> → <strong>I/O addresses</strong></li><li>Ändra <strong>Start address</strong></li></ol><div class="tip custom-block"><p class="custom-block-title">Adressplanering</p><p>Planera I/O-adresser tidigt i projektet. Använd ett konsekvent schema, ex:</p><ul><li><strong>IB0-IB99</strong>: Lokala I/O på PLC</li><li><strong>IB100-IB199</strong>: ET 200SP station 1</li><li><strong>IB200-IB299</strong>: ET 200SP station 2</li></ul></div><h2 id="kompilera-och-ladda-ner" tabindex="-1">Kompilera och ladda ner <a class="header-anchor" href="#kompilera-och-ladda-ner" aria-label="Permalink to &quot;Kompilera och ladda ner&quot;">​</a></h2><h3 id="_1-kompilera-hardvarukonfiguration" tabindex="-1">1. Kompilera hårdvarukonfiguration <a class="header-anchor" href="#_1-kompilera-hardvarukonfiguration" aria-label="Permalink to &quot;1. Kompilera hårdvarukonfiguration&quot;">​</a></h3><ol><li>Högerklicka på PLC → <strong>Compile</strong> → <strong>Hardware (rebuild all)</strong></li><li>Kontrollera att inga fel visas</li><li>Varningar om &quot;Not assigned&quot; kan ignoreras tillfälligt</li></ol><h3 id="_2-ladda-ner-till-plc" tabindex="-1">2. Ladda ner till PLC <a class="header-anchor" href="#_2-ladda-ner-till-plc" aria-label="Permalink to &quot;2. Ladda ner till PLC&quot;">​</a></h3><ol><li><strong>Online</strong> → <strong>Download to device</strong> → <strong>Hardware configuration</strong></li><li>Välj anslutningstyp (Profinet, USB)</li><li>Klicka <strong>Load</strong></li><li>Välj <strong>Start all</strong> om du vill starta modulerna direkt</li></ol><h3 id="_3-ladda-ner-till-io-devices" tabindex="-1">3. Ladda ner till IO Devices <a class="header-anchor" href="#_3-ladda-ner-till-io-devices" aria-label="Permalink to &quot;3. Ladda ner till IO Devices&quot;">​</a></h3><p>För HMI och vissa IO Devices:</p><ol><li>Högerklicka på enheten</li><li><strong>Download to device</strong> → <strong>Hardware and software</strong></li></ol><h2 id="diagnostik-och-felsokning" tabindex="-1">Diagnostik och felsökning <a class="header-anchor" href="#diagnostik-och-felsokning" aria-label="Permalink to &quot;Diagnostik och felsökning&quot;">​</a></h2><h3 id="online-status-i-tia-portal" tabindex="-1">Online-status i TIA Portal <a class="header-anchor" href="#online-status-i-tia-portal" aria-label="Permalink to &quot;Online-status i TIA Portal&quot;">​</a></h3><ol><li>Klicka <strong>Go online</strong> (grön pil i toolbar)</li><li>Enheter visar status med färgkodning: <ul><li>🟢 <strong>Grön</strong>: OK, kommunicerar</li><li>🟡 <strong>Gul</strong>: Varning (ex: diagnostik aktiv)</li><li>🔴 <strong>Röd</strong>: Fel (ex: ingen anslutning)</li></ul></li></ol><h3 id="diagnostikbuffert" tabindex="-1">Diagnostikbuffert <a class="header-anchor" href="#diagnostikbuffert" aria-label="Permalink to &quot;Diagnostikbuffert&quot;">​</a></h3><ol><li><strong>Online</strong> → <strong>Accessible devices</strong></li><li>Dubbelklicka på enhet</li><li><strong>Diagnostics</strong> → <strong>Diagnostic buffer</strong></li><li>Här ser du felhistorik och varningar</li></ol><h3 id="vanliga-profinet-fel" tabindex="-1">Vanliga Profinet-fel <a class="header-anchor" href="#vanliga-profinet-fel" aria-label="Permalink to &quot;Vanliga Profinet-fel&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Fel</th><th>Orsak</th><th>Lösning</th></tr></thead><tbody><tr><td><strong>BF LED blinkar</strong></td><td>Fel enhetsnamn</td><td>Tilldela korrekt Device name</td></tr><tr><td><strong>SF LED lyser</strong></td><td>Systemfel</td><td>Kontrollera diagnostikbuffert</td></tr><tr><td><strong>Ingen kommunikation</strong></td><td>IP-konflikt</td><td>Verifiera IP-adresser</td></tr><tr><td><strong>Timeout</strong></td><td>Kabelfel</td><td>Kontrollera kablar och switch</td></tr></tbody></table><h3 id="profinet-statistik" tabindex="-1">Profinet-statistik <a class="header-anchor" href="#profinet-statistik" aria-label="Permalink to &quot;Profinet-statistik&quot;">​</a></h3><ol><li>Markera PLC online</li><li><strong>Diagnostics</strong> → <strong>Profinet IO</strong> → <strong>IO system</strong></li><li>Visa: <ul><li><strong>Cycle time</strong> (bör vara stabil)</li><li><strong>Jitter</strong> (variation, bör vara låg)</li><li><strong>Data status</strong> (valid/invalid)</li></ul></li></ol><h2 id="resurser" tabindex="-1">Resurser <a class="header-anchor" href="#resurser" aria-label="Permalink to &quot;Resurser&quot;">​</a></h2><ul><li><a href="https://support.industry.siemens.com/cs/products?search=profinet%20configuration%20tia%20portal" target="_blank" rel="noreferrer">Siemens: PROFINET konfiguration (sökresultat)</a></li><li><a href="https://support.industry.siemens.com/cs/products?search=proneta" target="_blank" rel="noreferrer">PRONETA - Network Analysis Tool</a></li></ul><hr><p><strong>Relaterat:</strong></p><ul><li><a href="./profinet.html">Profinet-kommunikation</a></li><li><a href="./hmi-kommunikation.html">HMI-kommunikation</a></li><li><a href="./frekvensomriktare-komm.html">Frekvensomriktare-kommunikation</a></li></ul>`,57)])])}const k=t(n,[["render",l]]);export{p as __pageData,k as default};
